// Candidate runtime check in a private native export; never changes saved captures.
import assert from 'node:assert/strict';import {mkdtemp,cp,readFile,writeFile,rm} from 'node:fs/promises';import path from 'node:path';import {tmpdir} from 'node:os';import {chromium} from 'playwright';import {run} from '../../engine/pipeline.mjs';import {serveStatic} from '../../engine/static.mjs';
const artifact=path.resolve('artifacts/platform/cf7-heldout'),temp=await mkdtemp(path.join(tmpdir(),'cf7-feedback-'));let browser,server,release;const cases=[];
try{await cp(path.join(artifact,'project'),temp,{recursive:true});for(const file of ['form-export.mjs','component-forms.js'])await cp(path.resolve('scripts',file),path.join(temp,'scripts',file));const config=JSON.parse(await readFile(path.join(temp,'forms.json')));config.forms.find(f=>f.route==='/studio-news/').delivery={endpoint:'/feedback-test'};await writeFile(path.join(temp,'forms.json'),JSON.stringify(config));await run(process.execPath,['scripts/build.mjs'],{cwd:temp,timeout:120000});server=await serveStatic(path.join(temp,'output'));browser=await chromium.launch({channel:'chrome'});
 for(const width of [1440,390]){const page=await browser.newPage({viewport:{width,height:844}});let ok=true,posts=0;await page.route('**/feedback-test',async r=>{posts++;await new Promise(resolve=>release=resolve);await r.fulfill({status:ok==='invalid'?422:ok?200:503,contentType:'application/json',body:JSON.stringify(ok==='invalid'?{ok:false,errors:{'subscriber-email':'Use another email address.'}}:{ok})});});await page.goto(server.url+'/studio-news/',{waitUntil:'networkidle'});const form=page.locator('form.wpcf7-form');await form.locator('[name="full-name"]').fill('Fixture visitor');await form.locator('[name="subscriber-email"]').fill('fixture@example.test');await form.locator('[name="topics[]"]').selectOption(['Architecture']);await form.locator('[name="newsletter-policy"]').check();
 for(const success of [true,false,'invalid']){ok=success;await form.locator('[type=submit]').click();await page.waitForFunction(()=>document.querySelector('form.wpcf7-form').classList.contains('submitting'));assert.equal(await form.locator('.wpcf7-spinner').evaluate(e=>getComputedStyle(e).visibility),'visible');assert.equal(await form.locator('.wpcf7-response-output').isVisible(),false);release();await page.waitForFunction(()=>!document.querySelector('form.wpcf7-form').hasAttribute('aria-busy'));assert.equal(await form.locator('.wpcf7-response-output').isVisible(),true);const border=await form.locator('.wpcf7-response-output').evaluate(e=>getComputedStyle(e).borderTopColor);assert.equal(border,success==='invalid'?'rgb(255, 185, 0)':success?'rgb(70, 180, 80)':'rgb(220, 50, 50)');if(success==='invalid'){assert.equal(await form.locator('.wpcf7-not-valid-tip').textContent(),'Use another email address.');assert.equal(await form.locator('[name="subscriber-email"]').getAttribute('aria-invalid'),'true');await form.locator('[name="subscriber-email"]').fill('edited@example.test');assert.equal(await form.locator('.wpcf7-not-valid-tip').count(),0);}cases.push({width,state:success==='invalid'?'invalid':success?'accepted':'error',border,sourceSpinner:true});}assert.equal(posts,3);await form.evaluate(f=>f.reset());assert.equal(await form.locator('.wpcf7-response-output').isVisible(),false);await page.close();}
 await writeFile(path.join(artifact,'feedback-candidate-check.json'),JSON.stringify({candidateScripts:['form-export.mjs','component-forms.js'],cases,sourceSubmissions:0,aiCalls:0},null,2));console.log(JSON.stringify({cases:cases.length,sourceSubmissions:0,aiCalls:0}));
}finally{release?.();await browser?.close();await server?.close();await rm(temp,{recursive:true,force:true});}
